package com.bankingax.core.reservation;
import com.bankingax.core.api.*; import com.bankingax.core.tool.*; import java.time.*; import java.util.*; import java.sql.Timestamp; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
@RestController @RequestMapping("/api/v1/reservations") @ConditionalOnBean(JdbcTemplate.class) public class VisitReservationController {
 private final JdbcTemplate jdbc; private final InternalGatewayAuthenticator auth; private final StaffRankingPort ranking;
 public VisitReservationController(JdbcTemplate j,InternalGatewayAuthenticator a,StaffRankingPort r){jdbc=j;auth=a;ranking=r;}
 @PostMapping public ApiEnvelope<Item> create(@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestBody Create q){customer(actor,role,token);return ApiEnvelope.success(q.requestId,"VISIT_RESERVATION",null,q.caseId,null,create(actor,q));}
 @GetMapping public ApiEnvelope<List<Item>> list(@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestParam String requestId){customer(actor,role,token);return ApiEnvelope.success(requestId,"VISIT_RESERVATION",null,null,null,jdbc.query("select id,case_id,branch_id,assigned_staff_id,starts_at,status from visit_reservation where customer_id=? order by starts_at",(r,n)->row(r),actor));}
 @PostMapping("/{id}/cancel") public ApiEnvelope<Void> cancel(@PathVariable long id,@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestParam String requestId){customer(actor,role,token);if(jdbc.update("update visit_reservation set status='CANCELED',version=version+1 where id=? and customer_id=? and status in ('SELECTED','PENDING_ASSIGNMENT','CONFIRMED')",id,actor)==0)throw new DomainException("NOT_FOUND","Reservation unavailable.");return ApiEnvelope.success(requestId,"VISIT_RESERVATION",null,null,null,null);}
 @Transactional Item create(long customer,Create q){ var c=jdbc.query("select case_type,case_status,result_notified_at from service_case where id=? and customer_id=? for update",(r,n)->new Case(r.getString(1),r.getString(2),r.getTimestamp(3)),q.caseId,customer);if(c.isEmpty()||!"REVIEW_PASSED".equals(c.get(0).status)||c.get(0).notified==null)throw new DomainException("RESERVATION_NOT_ALLOWED","Staff PROCEED and customer notification are required."); List<Long> candidates=jdbc.query("select id from `user` where role='STAFF' and branch_id=? and is_active=true",(r,n)->r.getLong(1),q.branchId);Long staff=q.staffId; if(staff==null&&!candidates.isEmpty())staff=ranking.rank(candidates,c.get(0).type).get(0); if(staff==null)throw new DomainException("NEEDS_MANUAL_ASSIGNMENT","No eligible staff candidate."); if(!candidates.contains(staff))throw new DomainException("FORBIDDEN","Staff is not eligible for the branch."); try{jdbc.update("insert into visit_reservation(case_id,customer_id,branch_id,assigned_staff_id,starts_at,status) values(?,?,?,?,?,'CONFIRMED')",q.caseId,customer,q.branchId,staff,Timestamp.from(q.startsAt.toInstant()));}catch(org.springframework.dao.DataIntegrityViolationException e){throw new DomainException("RESERVATION_CONFLICT","Staff or case already has a reservation.",true);} return jdbc.queryForObject("select id,case_id,branch_id,assigned_staff_id,starts_at,status from visit_reservation where case_id=?",(r,n)->row(r),q.caseId);}
 private void customer(long a,ActorRole r,String t){auth.verify(t);if(r!=ActorRole.CUSTOMER)throw new DomainException("FORBIDDEN","Customer access is required.");} private static Item row(java.sql.ResultSet r)throws java.sql.SQLException{return new Item(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getTimestamp(5).toInstant(),r.getString(6));} private record Case(String type,String status,java.sql.Timestamp notified){} public record Create(String requestId,long caseId,long branchId,Long staffId,OffsetDateTime startsAt){} public record Item(long id,long caseId,long branchId,long staffId,Instant startsAt,String status){}
}
